Sorry but your cross for MIPS is broken:
1. struct user_desc is defined on X86 only, so if you see sys_set_thread_area redefinition on MIPS, then it's not a proper MIPS;
2. these constants are always defined on MIPS by <asm/sysmips.h>, so if they are not defined, then it's not a proper MIPS.

$ cat sigfpe.c
#include <assert.h>
#include <signal.h>
#include <stdio.h>
#include <unistd.h>

static void
handler(int sig, siginfo_t *info, void *ucontext)
{

	fprintf(stderr, "sig=%d, si_signo=%d, si_pid=%d, si_uid=%d\n",
		sig, info->si_signo, info->si_pid, info->si_uid);
}

static void
setup(int sig, sigset_t *mask)
{

	static const struct sigaction act = { .sa_sigaction = handler, .sa_flags = SA_SIGINFO };
	assert(!sigaction(sig, &act, NULL));
	assert(!sigaddset(mask, sig));
}

static void
test(int sig)
{

	assert(!raise(sig));
	assert(!kill(getpid(), sig));
}

int
main(void)
{

	sigset_t mask;
	assert(!sigemptyset(&mask));

	setup(SIGFPE, &mask);
	setup(SIGTERM, &mask);

	assert(!sigprocmask(SIG_UNBLOCK, &mask, NULL));

	test(SIGFPE);
	test(SIGTERM);

	return 0;
}

